<?php $this->assign('title', 'Suscripciones | CatOps Admin'); ?>
<div class="d-flex justify-content-between gap-3 mb-4 page-heading"><div><h1 class="h2 mb-1">Suscripciones</h1><p class="text-muted mb-0"><?= (int)$pagination['total'] ?> resultados.</p></div></div>
<section class="card admin-card mb-4"><div class="card-body"><form class="row g-2" method="get"><div class="col-12 col-md-5"><input class="form-control" name="q" value="<?= h($filters['q']) ?>" placeholder="Nombre o correo"></div><div class="col-6 col-md-2"><select class="form-select" name="status"><option value="">Estado</option><?php foreach (['active', 'expiring', 'grace_period', 'expired', 'suspended', 'cancelled'] as $status): ?><option value="<?= $status ?>" <?= $filters['status'] === $status ? 'selected' : '' ?>><?= $status ?></option><?php endforeach; ?></select></div><div class="col-6 col-md-3"><select class="form-select" name="plan"><option value="">Plan</option><?php foreach ($plans as $slug => $name): ?><option value="<?= h($slug) ?>" <?= $filters['plan'] === $slug ? 'selected' : '' ?>><?= h($name) ?></option><?php endforeach; ?></select></div><div class="col-12 col-md-2"><button class="btn btn-primary w-100">Buscar</button></div></form></div></section>
<section class="card admin-card"><div class="table-wrap"><table class="table align-middle"><thead><tr><th>Usuario</th><th>Plan</th><th>Estado</th><th>Inicio</th><th>Vence</th><th></th></tr></thead><tbody><?php foreach ($pagination['items'] as $subscription): ?><tr><td><?= h($subscription->user->email ?? '') ?></td><td><?= h($subscription->plan_slug) ?></td><td><span class="badge text-bg-secondary badge-status"><?= h($subscription->status) ?></span></td><td><?= h($subscription->starts_at) ?></td><td><?= h($subscription->ends_at ?: '—') ?></td><td><a class="btn btn-sm btn-outline-primary" href="/admin/subscriptions/<?= (int)$subscription->id ?>">Ver</a></td></tr><?php endforeach; ?></tbody></table></div><div class="card-body"><?= $this->element('admin_pagination', compact('pagination')) ?></div></section>
